(()=>{document.querySelectorAll("[data-drawer-search]").forEach(e=>{const s=e.querySelector("input"),t=e.querySelector(".drawer-search-results"),n=e.querySelector('[role="status"]');let i,o=0;const a=()=>(i||=fetch(e.dataset.indexUrl).then(e=>{if(!e.ok)throw new Error;return e.json()}).then(e=>new Fuse(e,{keys:["title","description","tags","series","content"],threshold:.35,ignoreLocation:!0})).catch(e=>{throw i=0[0],e}));s.addEventListener("input",async()=>{const e=++o;t.replaceChildren();const i=s.value.trim();if(!i){n.textContent="";return}n.textContent="Searching…";try{const s=await a();if(o!==e)return;for(const{item:e}of s.search(i,{limit:10})){const n=new URL(e.uri,location.href);if(n.origin!==location.origin||!["http:","https:"].includes(n.protocol))continue;const o=document.createElement("a");o.href=n.href;const a=document.createElement("strong");a.textContent=e.title;const r=document.createElement("small");r.textContent=(e.description||e.content||"").slice(0,160),o.append(a,r),t.append(o)}n.textContent=`${t.childElementCount} results`}catch{o===e&&(n.textContent="Search unavailable. Please try again.")}}),e.addEventListener("keydown",e=>{const i=[...t.querySelectorAll("a")];if(e.key==="Escape")e.preventDefault(),e.stopPropagation(),++o,s.value="",t.replaceChildren(),n.textContent="",s.focus();else if(["ArrowDown","ArrowUp"].includes(e.key)&&i.length){e.preventDefault(),e.stopPropagation();const t=i.indexOf(document.activeElement);i[e.key==="ArrowDown"?(t+1)%i.length:t<=0?i.length-1:t-1].focus()}})})})()